spawn.example:
const { Vector3 } = kcds.math;

const trebuchet = kcds.world.SiegeEngine.spawn('trebuchet', new Vector3(100, 200, 10));
trebuchet.usable = true;
trebuchet.damage = 400;
trebuchet.maxHealth = 1000;
trebuchet.ammo = 10;

kcds.core.Events.on('siegeEngineReady', (engine) => {
  engine.fire(new Vector3(250, 300, 12));
});
trebuchet.load();

spawn.exampleCs:
var trebuchet = SiegeEngine.Spawn("trebuchet", new Vector3(100, 200, 10));
trebuchet.Usable = true;
trebuchet.Damage = 400;
trebuchet.MaxHealth = 1000;
trebuchet.Ammo = 10;

Events.On("siegeEngineReady", (JsValue engine) =>
{
    engine.Call("fire", new Vector3(250, 300, 12));
});
trebuchet.Load();

load.example:
const answer = trebuchet.load();
if (!answer.accepted) {
  console.info(`no reload: ${answer.reason}`);
}

load.exampleCs:
var answer = trebuchet.Load();
if (!answer["accepted"])
{
    Log.Info($"no reload: {answer["reason"]}");
}

aim.example:
const { accepted, seconds } = trebuchet.aim(new kcds.math.Vector3(250, 300, 12));
if (accepted) {
  console.info(`turning for ${seconds} s`);
}

aim.exampleCs:
var accepted = trebuchet.Aim(new Vector3(250, 300, 12))["accepted"];
var seconds = trebuchet.Aim(new Vector3(250, 300, 12))["seconds"];
if (accepted)
{
    Log.Info($"turning for {seconds} s");
}

inReach.example:
const problem = trebuchet.inReach(target);
if (problem !== '') {
  kcds.core.Chat.sendToPlayer(player, `Out of reach: ${problem}`);
}

inReach.exampleCs:
var problem = trebuchet.InReach(target);
if (problem != "")
{
    Chat.SendToPlayer(player, $"Out of reach: {problem}");
}
